class Solution:
    def totalFruit(self, tree: List[int]) -> int:
        table = collections.Counter()
        types = maxCount = start = 0
        for i, t in enumerate(tree):
            table[t] += 1
            if table[t] == 1:
                types += 1
            while types > 2:
                table[tree[start]] -= 1
                if table[tree[start]] == 0:
                    types -= 1
                start += 1
            maxCount = max(maxCount, i - start + 1)
        return maxCount


